package dev.sablelife.testing;
import dev.sablelife.SableLife;
import dev.sablelife.module.*;
import net.minecraft.gametest.framework.*;
import net.neoforged.neoforge.gametest.*;
import net.minecraft.world.phys.Vec3;
@GameTestHolder("sablelife_blast_tests") @PrefixGameTestTemplate(false)
public final class ModuleColorGameTests {
 @GameTest(template="combat",batch="rgb_controls") public static void EveryPresetCanToggleCustomAndKeepBothColors(GameTestHelper h){for(String type:java.util.List.of("mortar","ground_strike","laser","quake","pull","slash"))for(var key:ModuleColors.keys(type)){
  var m=new VirtualModule(type);m.edit(key,2,"");var preset=ModuleColors.vector(m,key);h.assertTrue(m.edit(key+"Rgb",1,"")&&ModuleColors.vector(m,key).distance(preset)<.007,"RGB initial value did not match preset: "+key);m.edit(key+"Red",80,"");m.edit(key+"Green",40,"");m.edit(key+"Blue",200,"");var custom=ModuleColors.vector(m,key);m.edit(key+"Rgb",0,"");h.assertTrue(ModuleColors.vector(m,key).equals(preset)&&ModuleColors.display(m,ModuleFields.forType(type),6).stream().noneMatch(f->f.key().equals(key+"Red")),"Collapsed mode did not restore preset/hide RGB: "+key);var saved=VirtualModule.load(m.save());saved.edit(key+"Rgb",1,"");h.assertTrue(ModuleColors.vector(saved,key).equals(custom),"Custom RGB lost on toggle/reload: "+key);var visible=ModuleColors.display(saved,ModuleFields.forType(type),6);int index=0;for(;index<visible.size();index++)if(visible.get(index).key().equals(key))break;h.assertTrue(index<visible.size()&&visible.stream().noneMatch(f->ModuleColors.parent(type,f.key())!=null),"Picker still exposed separate dashboard RGB rows");h.assertTrue(saved.edit(key+"Rgb",1,"12,34,56")&&saved.value(key+"Red")==12&&saved.value(key+"Green")==34&&saved.value(key+"Blue")==56,"Atomic picker update failed");}h.succeed();}
 @GameTest(template="combat",batch="rgb_atomic") public static void CollapseSavesTypedChannelsAsOneEditAndRejectsInvalidValues(GameTestHelper h){var m=new VirtualModule("laser");m.edit("beamColorRgb",1,"");h.assertTrue(m.edit("beamColorRgb",0,"80,40,200")&&m.value("beamColorRgb")==0&&m.value("beamColorBlue")==200,"Atomic collapse lost typed color");h.assertTrue(!m.edit("beamColorRgb",0,"20,NaN,10")&&!m.edit("beamColorRgb",0,"20,256,10")&&m.value("beamColorRed")==80,"Invalid collapse partially changed saved color");h.succeed();}
 @GameTest(template="combat",batch="rgb_independent") public static void PullColorsRemainIndependentAndOldSlashMigrates(GameTestHelper h){var m=new VirtualModule("pull");m.edit("pullWarningColorRgb",1,"");m.edit("pullWarningColorRed",40,"");h.assertTrue(m.value("pullCenterColorRgb")==0&&m.value("pullCenterColor")==4,"Warning changed center color");var old=new VirtualModule("slash").save();old.remove("ColorControlsVersion");var settings=old.getCompound("Settings");settings.putDouble("slashRed",42);settings.putDouble("slashGreen",111);settings.putDouble("slashBlue",222);var migrated=VirtualModule.load(old);h.assertTrue(migrated.value("slashColorRgb")==1&&migrated.value("slashColorRed")==42&&migrated.value("slashColorGreen")==111&&migrated.value("slashColorBlue")==222,"Old slash RGB lost");h.succeed();}
 @GameTest(template="combat",batch="rgb_mortar") public static void MortarCustomColorSnapshotsBeforeFirstRingAndSurvivesReload(GameTestHelper h){var m=new VirtualModule("mortar");m.edit("mortarWarningColorRgb",1,"");m.edit("mortarWarningColorRed",80,"");m.edit("mortarWarningColorGreen",40,"");m.edit("mortarWarningColorBlue",200,"");var shot=new dev.sablelife.attack.ModuleShot(h.getLevel(),h.absoluteVec(new Vec3(3,8,3)),Vec3.ZERO,m,new dev.sablelife.heart.HeartBlockEntity(h.absolutePos(new net.minecraft.core.BlockPos(2,4,2)),SableLife.HEART.get().defaultBlockState()));var saved=shot.saveWithoutId(new net.minecraft.nbt.CompoundTag());int color=ModuleColors.packed(m,"mortarWarningColor");h.assertTrue(saved.getInt("MortarWarningColor")==color,"First shot did not snapshot custom color");var restored=new dev.sablelife.attack.ModuleShot(SableLife.MODULE_SHOT.get(),h.getLevel());restored.load(saved);h.assertTrue(restored.saveWithoutId(new net.minecraft.nbt.CompoundTag()).getInt("MortarWarningColor")==color&&dev.sablelife.attack.ShotTrajectory.warningColor(color).getColor().distance(ModuleColors.vector(m,"mortarWarningColor"))<.001,"Reload/custom dust color lost");h.succeed();}
 @GameTest(template="combat",batch="rgb_picker_math") public static void ColorPickerRoundTripsRgbAndSynchronizesHueSquareAndChannels(GameTestHelper h){
  for(int r=0;r<=255;r+=17)for(int g=0;g<=255;g+=17)for(int b=0;b<=255;b+=17){int rgb=(r<<16)|(g<<8)|b;var model=new dev.sablelife.client.ColorPickerModel(rgb);h.assertTrue(model.rgb()==rgb&&dev.sablelife.client.ColorPickerModel.toRgb(model.hue(),model.saturation(),model.value())==rgb,"HSV roundtrip changed stored RGB");}
  var model=new dev.sablelife.client.ColorPickerModel(0xFF0000);model.square(.5,.5);h.assertTrue(model.rgb()==0x804040,"Square did not update RGB channels");model.hue(1/3.);h.assertTrue(model.rgb()==0x408040,"Hue strip did not update RGB channels");model.rgb(0x123456);h.assertTrue(dev.sablelife.client.ColorPickerModel.toRgb(model.hue(),model.saturation(),model.value())==0x123456,"Numeric input did not synchronize HSV cursor");
  var m=new VirtualModule("laser");h.assertTrue(m.edit("beamColorRgb",1,"12,34,56")&&m.value("beamColorRed")==12&&m.value("beamColorGreen")==34&&m.value("beamColorBlue")==56&&!m.edit("beamColorRgb",1,"12,256,56")&&m.value("beamColorGreen")==34,"Atomic custom picker edit accepted invalid partial update");h.succeed();
 }
}
